fn r#test_utf16_project_keeps_valid_input_and_rejects_entities(__args: Args) -> Object {
    let mut r#tmp_path = __args.bind(0, "tmp_path", None);
    let mut r#denied = Object::Unbound;
    let mut r#path = Object::Unbound;
    let mut r#valid = Object::Unbound;
    r#path = object::div(
        &object::local(&r#tmp_path, "tmp_path"),
        &object::str_("project.csproj"),
    );
    object::call_method(
        &object::local(&r#path, "path"),
        "write_bytes",
        Args::new(
            vec![object::call_method(
                &object::str_(
                    "<?xml version=\"1.0\" encoding=\"utf-16\"?><Project><PropertyGroup><TargetFramework>net8.0</TargetFramework></PropertyGroup></Project>",
                ),
                "encode",
                Args::new(vec![object::str_("utf-16")], vec![]),
            )],
            vec![],
        ),
    );
    r#valid = object::call(
        &object::name("backend.context_graph.extract.extract_csproj"),
        Args::new(vec![object::local(&r#path, "path")], vec![]),
    );
    object::assert_(
        &object::getitem(&object::local(&r#valid, "valid"), &object::str_("nodes")),
        "unit/test_context_graph_extract.py:519",
        None,
    );
    object::assert_(
        &object::not_in(&object::str_("error"), &object::local(&r#valid, "valid")),
        "unit/test_context_graph_extract.py:520",
        None,
    );
    object::call_method(
        &object::local(&r#path, "path"),
        "write_bytes",
        Args::new(
            vec![object::call_method(
                &object::str_(
                    "<?xml version=\"1.0\" encoding=\"utf-16\"?><!DOCTYPE Project [<!ENTITY injected \"untrusted-expanded-value\">]><Project><PropertyGroup><TargetFramework>&injected;</TargetFramework></PropertyGroup></Project>",
                ),
                "encode",
                Args::new(vec![object::str_("utf-16")], vec![]),
            )],
            vec![],
        ),
    );
    r#denied = object::call(
        &object::name("backend.context_graph.extract.extract_csproj"),
        Args::new(vec![object::local(&r#path, "path")], vec![]),
    );
    object::assert_(
        &object::cmp_eq(
            &object::getitem(&object::local(&r#denied, "denied"), &object::str_("nodes")),
            &object::list(vec![]),
        ),
        "unit/test_context_graph_extract.py:527",
        None,
    );
    object::assert_(
        &object::in_(&object::str_("error"), &object::local(&r#denied, "denied")),
        "unit/test_context_graph_extract.py:528",
        None,
    );
    object::assert_(
        &object::not_in(
            &object::str_("untrusted-expanded-value"),
            &object::call(
                &object::name("builtins.str"),
                Args::new(vec![object::local(&r#denied, "denied")], vec![]),
            ),
        ),
        "unit/test_context_graph_extract.py:529",
        None,
    );
    Object::None
}

